    valid = 0;
} else if (adcs_vec3_norm(sa_input.sun) <= ADCS_EPS_NORM ||
           adcs_vec3_norm(sa_input.boresight) <= ADCS_EPS_NORM) {
    valid = 0;
} else if (sa_config.exit_cosine < -1.0 || sa_config.exit_cosine > 1.0 ||
           sa_config.enter_cosine < -1.0 || sa_config.enter_cosine > 1.0 ||
           sa_config.exit_cosine >= sa_config.enter_cosine) {
    valid = 0;
}

if (!valid) {
    sa_state.mode = SA_FAULT;
    sa_output.mode = SA_FAULT;
    sa_output.cosine = 0.0;
    sa_output.angle_rad = 0.0;
    sa_output.correction_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

/* enable == 0 分支 */
if (sa_input.enable == 0) {
    sa_state.mode = SA_OFF;
    sa_output.mode = SA_OFF;
    sa_output.cosine = 0.0;
    sa_output.angle_rad = 0.0;
    sa_output.correction_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

/* 归一化向量 */
(void)adcs_vec3_normalize(sa_input.sun, ADCS_EPS_NORM, &sun_n);
(void)adcs_vec3_normalize(sa_input.boresight, ADCS_EPS_NORM, &bore_n);

/* 计算 cosine 与叉轴 */
cosine = adcs_vec3_dot(&bore_n, &sun_n);
axis = adcs_vec3_cross(&bore_n, &sun_n);
cross_norm = adcs_vec3_norm(&axis);

/* 模式迁移 */
if (sa_state.mode == SA_OFF) {
    if (cosine >= sa_config.enter_cosine)
        sa_state.mode = SA_ACTIVE;
    else
        sa_state.mode = SA_OFF;
} else if (sa_state.mode == SA_ACTIVE) {
    if (cosine <= sa_config.exit_cosine)
        sa_state.mode = SA_OFF;
    else
        sa_state.mode = SA_ACTIVE;
} else {
    sa_state.mode = SA_FAULT;
}

/* 输出 angle 与 correction axis */
angle = acos(ADCS_CLAMP(cosine, -1.0, 1.0));
if (cross_norm <= ADCS_EPS_COLLINEAR) {
    axis = (adcs_vec3_t){0.0, 0.0, 0.0};
} else {
    axis = adcs_vec3_scale(&axis, 1.0 / cross_norm);
}

sa_output.mode = sa_state.mode;
sa_output.cosine = cosine;
sa_output.angle_rad = angle;
sa_output.correction_axis = axis;

