            (sa_config.exit_cosine >= -1.0) && (sa_config.enter_cosine <= 1.0) &&
            (sa_config.exit_cosine < sa_config.enter_cosine);

if (!config_ok || (sa_input.sun == NULL) || (sa_input.boresight == NULL) ||
    (!adcs_is_finite_vec3(sa_input.sun)) || (!adcs_is_finite_vec3(sa_input.boresight))) {
    sa_state.mode = SA_FAULT;
    sa_output.mode = SA_FAULT;
    sa_output.cosine = 0.0;
    sa_output.angle_rad = 0.0;
    return;
}

n_sun = adcs_vec3_norm(sa_input.sun);
n_bore = adcs_vec3_norm(sa_input.boresight);
if ((n_sun <= ADCS_EPS_NORM) || (n_bore <= ADCS_EPS_NORM)) {
    sa_state.mode = SA_FAULT;
    sa_output.mode = SA_FAULT;
    sa_output.cosine = 0.0;
    sa_output.angle_rad = 0.0;
    return;
}

if ((sa_input.enable != 0) && (sa_input.enable != 1)) {
    sa_state.mode = SA_FAULT;
    sa_output.mode = SA_FAULT;
    sa_output.cosine = 0.0;
    sa_output.angle_rad = 0.0;
    return;
}

