    sa_output.correction_axis = adcs_vec3_scale(&cross_v, 1.0 / cross_norm);

sa_output.cosine = c;
sa_output.angle_rad = acos(c);

if (sa_input.enable == 0) {
    sa_state.mode = SA_OFF;
    sa_output.mode = SA_OFF;
    return;
}

if (sa_state.mode == SA_OFF)
    next_mode = (c >= sa_config.enter_cosine) ? SA_ACTIVE : SA_OFF;
else if (sa_state.mode == SA_ACTIVE)
    next_mode = (c <= sa_config.exit_cosine) ? SA_OFF : SA_ACTIVE;
else
    next_mode = (c >= sa_config.enter_cosine) ? SA_ACTIVE : SA_OFF;

sa_state.mode = next_mode;
sa_output.mode = next_mode;

